// модуль объекта ВВОДИМОГО документа (здесь — поступление из заказа)
Procedure Filling(Source, StandartProcessing)
{
    If (Not ValueIsFilled(Source)) {
        Return;                        // просто новый документ: только умолчания
    }
    // шапка по именам; строки — из того, что по заказу ещё открыто
    Counterparty = Source.Counterparty;
    Warehouse = Source.Warehouse;
    foreach (line In Source.Goods) {
        var row = Goods.Add();
        row.Item = line.Item;
        row.Quantity = line.Quantity;
    }
}

// то же самое из кода
var doc = Documents.GoodsReceipt.CreateDocument();
